const languageIndexes = {
  English: 0,
  French: 1,
  Spanish: 2,
  Portuguese: 3,
  German: 4,
};

const dictionaries = Object.fromEntries(
  Object.entries(languageIndexes).map(([language, index]) => [
    language,
    Object.fromEntries(entries.map((entry) => [entry[0], entry[index]])),
  ])
);

export const APP_TRANSLATION_KEYS = Object.keys(dictionaries.English);

export function translateAppText(language, text) {
  if (typeof text !== 'string') return text;
  const trimmedText = text.trim();
  if (trimmedText !== text) {
    const translated = translateAppText(language, trimmedText);
    const leadingSpace = /^\s/.test(text) ? ' ' : '';
    const trailingSpace = /\s$/.test(text) ? ' ' : '';
    return `${leadingSpace}${translated}${trailingSpace}`;
  }
  const settingsSuffixes = [
    ' Browser-saved settings are shown and were not changed.',
    ' Any browser-saved settings were preserved.',
  ];
  const settingsSuffix = settingsSuffixes.find((suffix) => text.endsWith(suffix));
  if (settingsSuffix) {
    const message = text.slice(0, -settingsSuffix.length);
    const translatedMessage = dictionaries[language]?.[message] ?? message;
    const translatedSuffix =
      dictionaries[language]?.[settingsSuffix.trim()] ?? settingsSuffix.trim();
    return `${translatedMessage} ${translatedSuffix}`;
  }
  for (const prefix of [
    'Price refresh failed; showing the last successful prices.',
    'Prices are unavailable.',
  ]) {
    if (text.startsWith(prefix) && text.length > prefix.length) {
      return `${dictionaries[language]?.[prefix] ?? prefix} ${text.slice(prefix.length).trim()}`;
    }
  }
  const withdrawalBalanceMatch = text.match(
    /^The amount exceeds your available (.+) balance of (.+)\.$/
  );
  if (withdrawalBalanceMatch) {
    const [, asset, balance] = withdrawalBalanceMatch;
    const messages = {
      French: `Le montant dépasse votre solde disponible pour ${asset} (${balance}).`,
      Spanish: `El importe supera tu saldo disponible de ${asset} (${balance}).`,
      Portuguese: `O valor excede seu saldo disponível de ${asset} (${balance}).`,
      German: `Der Betrag überschreitet Ihr verfügbares Guthaben für ${asset} (${balance}).`,
    };
    return messages[language] ?? text;
  }
  const transferMatch = text.match(/^(Admin send|Transfer) of (.+) completed\.$/);
  if (transferMatch) {
    const [, action, details] = transferMatch;
    const actionText = dictionaries[language]?.[action] ?? action;
    const ofText = dictionaries[language]?.of ?? 'of';
    const completedText = dictionaries[language]?.['completed.'] ?? 'completed.';
    return `${actionText} ${ofText} ${details} ${completedText}`;
  }
  const creditedMatch = text.match(/^Credited (.+) to (.+)\.$/);
  if (creditedMatch) {
    const [_, amount, recipient] = creditedMatch;
    const credited = {
      French: 'Crédit de',
      Spanish: 'Se acreditaron',
      Portuguese: 'Crédito de',
      German: 'Gutgeschrieben wurden',
    }[language] || 'Credited';
    const to = { French: 'à', Spanish: 'a', Portuguese: 'para', German: 'an' }[language] || 'to';
    return `${credited} ${amount} ${to} ${recipient}.`;
  }
  return dictionaries[language]?.[text] ?? text;
}

export function getAppTranslationKeyCounts() {
  return Object.fromEntries(
    Object.entries(dictionaries).map(([language, dictionary]) => [
      language,
      Object.keys(dictionary).length,
    ])
  );
}
